class SquareCounter {
  private pts: number[][] = [];

  add(point: number[]): void {
    this.pts.push(point);
  }

  count(point: number[]): number {
    const [x, y] = point;
    let total = 0;
    for (const [px, py] of this.pts) {
      if (px === x || Math.abs(px - x) !== Math.abs(py - y)) continue;
      let a = 0, b = 0;
      for (const [qx, qy] of this.pts) {
        if (qx === x && qy === py) a++;
        if (qx === px && qy === y) b++;
      }
      total += a * b;
    }
    return total;
  }
}

