  private cnt = new Map<number, number>();
  private key(x: number, y: number): number { return x * 1001 + y; }

  add(point: number[]): void {
    const k = this.key(point[0], point[1]);
    this.cnt.set(k, (this.cnt.get(k) ?? 0) + 1);
  }

  count(point: number[]): number {
    const [x, y] = point;
    let total = 0;
    for (const [k, c] of this.cnt) {
      const px = Math.floor(k / 1001), py = k % 1001;
      if (px === x || Math.abs(px - x) !== Math.abs(py - y)) continue;
      total += c * (this.cnt.get(this.key(x, py)) ?? 0) * (this.cnt.get(this.key(px, y)) ?? 0);
    }
    return total;
  }
}

