class SquareCounter {
  private cnt = new Map<number, number>();
  private byX = new Map<number, Map<number, number>>();
  private key(x: number, y: number): number { return x * 1001 + y; }

  add(point: number[]): void {
    const [x, y] = point, k = this.key(x, y);
    this.cnt.set(k, (this.cnt.get(k) ?? 0) + 1);
    if (!this.byX.has(x)) this.byX.set(x, new Map());
    const col = this.byX.get(x)!;
    col.set(y, (col.get(y) ?? 0) + 1);
  }

  count(point: number[]): number {
    const [x, y] = point;
    const col = this.byX.get(x);
    if (!col) return 0;
    let total = 0;
    for (const [py, c] of col) {
      if (py === y) continue;
      const d = py - y;
      for (const px of [x + d, x - d]) {
        total += c * (this.cnt.get(this.key(px, py)) ?? 0) * (this.cnt.get(this.key(px, y)) ?? 0);
      }
    }
    return total;
  }
}

